ee:message.ee:set-payload:
%dw 2.0
output application/json

// Recursive function to render nested Objects as tables and Arrays as lists
fun renderHTML(value) = 
    if (value is Object)
        "<table border='1' cellpadding='5' style='border-collapse: collapse; width: 100%;'>" ++
        (
            (value pluck (v, k) -> 
                "<tr>
                    <td bgcolor='#f9f9f9' style='width: 30%;'><b>" ++ (k as String) ++ ":</b></td>
                    <td>" ++ renderHTML(v) ++ "</td>
                </tr>"
            ) joinBy ""
        ) ++
        "</table>"
    else if (value is Array)
        "<ul>" ++ 
        (
            (value map (v) -> 
                "<li>" ++ renderHTML(v) ++ "</li>"
            ) joinBy ""
        ) ++ 
        "</ul>"
    else 
        (value as String default "")

// Dynamically generate the main rows (Removed the invalid do block)
var dynamicRows = (vars.error pluck (value, key) -> 
    "<tr>
      <td bgcolor='#f2f2f2' style='width: 20%;'><b>" ++ (key as String) ++ ":</b></td>
      <td>" ++ renderHTML(value) ++ "</td>
    </tr>"
) joinBy ""

---
{
  "message": {
    "subject": Mule::p('mule.env') ++ " - MuleSoft - Error Alert - " ++ Mule::p('app.name'),
    "body": {
      "contentType": "HTML",
      "content": "<h3> MuleSoft - Error Alert - $(p('app.name') default 'Unknown App')</h3>
                  <p>Hello,</p>
                  <p>An error occurred in the Mule Application. Please find the details below:</p>
                  <table border='1' cellpadding='5' style='border-collapse: collapse; width: 100%;'>"
                  ++ dynamicRows ++
                  "</table>
                  <p>Please check the logs to investigate the issue further.</p>"
    },
    "toRecipients": (Mule::p('email.emailTo') default "" splitBy ";") map ((email) -> {
      "emailAddress": {
        "address": trim(email)
      }
    })
  },
  "saveToSentItems": "true"
}
